1	/**
2	 * Operator command rules (CS-9): prefix rules that decide, for a shell command the model wants to run, whether Nexus asks
3	 * the operator, runs it without asking, or refuses it. Modelled on the data-not-code shape of Codex's `execpolicy`:
4	 * a three-level outcome (allow < prompt < forbidden), load-time examples that must agree with the rule, and a record of
5	 * which rule decided.
6	 *
7	 *   ~/.config/nexus/command_rules.json (operator home only; a project file is never read)
8	 *   { "version": 1, "rules": [
9	 *       { "prefix": ["git", ["status", "log", "diff"]], "decision": "allow", "justification": "read-only git",
10	 *         "match": ["git status", "git diff --stat"], "notMatch": ["git push"] },
11	 *       { "prefix": ["git", "push"], "decision": "prompt", "match": ["git push origin main"] },
12	 *       { "prefix": ["rm", "-rf"], "decision": "forbidden", "justification": "never recursive-delete", "match": ["rm -rf build"] } ] }
13	 *
14	 * What a rule can and cannot do:
15	 * - A rule narrows or widens the *prompt*, never the other controls. Read-only mode, the sandbox, verification-path
16	 *   protection and the unknown-outcome re-issue gate still apply to a command a rule allows.
17	 * - `allow` is granted only when every segment of the command (split on `;`, `&&`, `||`, `|`, `&`) matches an allow rule
18	 *   and the command contains no shell-active character (`$ ` ( ) { } < > * ? !`, a backslash, a newline, or a `~` or `#` that
19	 *   starts a word) anywhere: a heuristic
20	 *   never qualifies. A command that cannot be allowed falls back to the normal approval policy.
21	 * - `prompt` and `forbidden` match any segment, so they cannot be dodged by chaining. Like the destructive-command
22	 *   tripwire this is a convenience layer, not a sandbox: a command hidden in `$(...)` or a script is not seen, and the
23	 *   sandbox remains the security boundary.
24	 * - `forbidden` holds in every mode, including `--yes`. `prompt` holds unless the operator passed `--yes`.
25	 * - A file that fails to load (bad field, or an example the rules contradict) is refused whole and reported; the normal
26	 *   approval policy then applies, so a broken file never silently widens or narrows anything.
27	 */
28	import fs from "node:fs";
29	import { splitSubcommands } from "../security.js";
30	
31	export type RuleDecision = "allow" | "prompt" | "forbidden";
32	
33	const SEVERITY: Record<RuleDecision, number> = { allow: 0, prompt: 1, forbidden: 2 };
34	const DECISIONS: readonly RuleDecision[] = ["allow", "prompt", "forbidden"];
35	const KNOWN_FIELDS = new Set(["prefix", "decision", "justification", "match", "notMatch"]);
36	const MAX_RULES = 200;
37	const MAX_PREFIX_TOKENS = 16;
38	const MAX_EXAMPLES = 20;
39	const MAX_TEXT = 200;
40	/** Characters that let a shell run or redirect something this module does not parse. Their presence anywhere blocks `allow`. */
41	const SHELL_ACTIVE = /[\n\r$`(){}<>*?!\\]|(?:^|\s)[~#]/;
42	
43	export interface CommandRule {
44	  /** Position in the file, 1-based, as the operator counts rules. */
45	  index: number;
46	  /** One entry per command word; each entry lists the words accepted at that position. */
47	  prefix: readonly (readonly string[])[];
48	  decision: RuleDecision;
49	  justification?: string;
50	  match: readonly string[];
51	  notMatch: readonly string[];
52	}
53	
54	export interface CommandRuleSet {
55	  rules: readonly CommandRule[];
56	  /** Where the rules came from, for the report; absent for an empty set. */
57	  file?: string;
58	}
59	
60	export const NO_COMMAND_RULES: CommandRuleSet = { rules: [] };
61	
62	/** Which rule decided and what it did to the approval, kept for the session export. */
63	export interface CommandRuleDecision {
64	  timestamp: string;
65	  tool: string;
66	  /** The command, redacted and truncated. */
67	  command: string;
68	  decision: RuleDecision;
69	  /** What changed: a prompt removed, a prompt added, or the command refused. */
70	  effect: "allowed without prompt" | "prompted" | "refused";
71	  rule: number;
72	  /** Every rule that took part (an allowed chain can involve several). */
73	  rules: number[];
74	  prefix: string;
75	  justification?: string;
76	}
77	
78	export interface CommandVerdict {
79	  decision: RuleDecision;
80	  /** The rule that decided (the most severe one for prompt/forbidden, the first allow for allow). */
81	  rule: CommandRule;
82	  rules: CommandRule[];
83	}
84	
85	const isObject = (v: unknown): v is Record<string, unknown> => Boolean(v) && typeof v === "object" && !Array.isArray(v);
86	
87	function text(value: unknown, field: string, required = false): string | undefined {
88	  if (value === undefined) {
89	    if (required) throw new Error(`${field}: required`);
90	    return undefined;
91	  }
92	  if (typeof value !== "string" || !value.trim() || value.length > MAX_TEXT) throw new Error(`${field}: must be a non-empty string of at most ${MAX_TEXT} characters`);
93	  return value;
94	}
95	
96	function parsePrefix(raw: unknown, field: string): (readonly string[])[] {
97	  if (!Array.isArray(raw) || raw.length === 0 || raw.length > MAX_PREFIX_TOKENS) throw new Error(`${field}: must be a non-empty array of at most ${MAX_PREFIX_TOKENS} words`);
98	  return raw.map((entry, i) => {
99	    const alternatives = Array.isArray(entry) ? entry : [entry];
100	    if (alternatives.length === 0 || alternatives.length > 16) throw new Error(`${field}[${i}]: a list of alternatives needs 1 to 16 words`);
101	    return alternatives.map((word, j) => {
102	      if (typeof word !== "string" || !word || word.length > MAX_TEXT || /\s/.test(word)) throw new Error(`${field}[${i}]${Array.isArray(entry) ? `[${j}]` : ""}: must be a single word with no whitespace`);
103	      return word;
104	    });
105	  });
106	}
107	
108	function parseExamples(raw: unknown, field: string): string[] {
109	  if (raw === undefined) return [];
110	  if (!Array.isArray(raw) || raw.length > MAX_EXAMPLES) throw new Error(`${field}: must be an array of at most ${MAX_EXAMPLES} example commands`);
111	  return raw.map((example, i) => {
112	    if (typeof example !== "string" || !example.trim() || example.length > 400) throw new Error(`${field}[${i}]: must be a non-empty command string`);
113	    return example;
114	  });
115	}
116	
117	function matchesSegment(rule: CommandRule, segment: readonly string[]): boolean {
118	  if (segment.length < rule.prefix.length) return false;
119	  return rule.prefix.every((alternatives, i) => alternatives.includes(segment[i]));
120	}
121	
122	/**
123	 * The rules' verdict on a command, or null when no rule applies (the normal approval policy then decides).
124	 * `forbidden` and `prompt` act on any matching segment; `allow` needs every segment allowed and no shell-active character.
125	 */
126	export function decideCommand(set: CommandRuleSet, command: string): CommandVerdict | null {
127	  if (set.rules.length === 0 || typeof command !== "string" || !command.trim()) return null;
128	  const segments = splitSubcommands(command);
129	  if (segments.length === 0) return null;
130	  let strictest: { decision: RuleDecision; rule: CommandRule } | undefined;
131	  const perSegment: (CommandRule | undefined)[] = [];
132	  for (const segment of segments) {
133	    let allowRule: CommandRule | undefined;
134	    for (const rule of set.rules) {
135	      if (!matchesSegment(rule, segment)) continue;
136	      if (rule.decision === "allow") allowRule ??= rule;
137	      else if (!strictest || SEVERITY[rule.decision] > SEVERITY[strictest.decision]) strictest = { decision: rule.decision, rule };
138	    }
139	    perSegment.push(allowRule);
140	  }
141	  if (strictest) {
142	    const involved = set.rules.filter((r) => segments.some((s) => matchesSegment(r, s)) && SEVERITY[r.decision] === SEVERITY[strictest!.decision]);
143	    return { decision: strictest.decision, rule: strictest.rule, rules: involved };
144	  }
145	  if (!SHELL_ACTIVE.test(command) && perSegment.every((r) => r !== undefined)) {
146	    const rules = [...new Set(perSegment as CommandRule[])];
147	    return { decision: "allow", rule: rules[0], rules };
148	  }
149	  return null;
150	}
151	
152	/** Parses and validates a rules document. Every error names the field. Examples are checked against the whole set. */
153	export function parseCommandRules(doc: unknown, file?: string): CommandRuleSet {
154	  if (!isObject(doc)) throw new Error("command_rules.json: must be an object");
155	  for (const key of Object.keys(doc)) if (key !== "version" && key !== "rules") throw new Error(`command_rules.json.${key}: unknown field`);
156	  if (doc.version !== 1) throw new Error("command_rules.json.version: must be 1");
157	  if (!Array.isArray(doc.rules) || doc.rules.length > MAX_RULES) throw new Error(`command_rules.json.rules: must be an array of at most ${MAX_RULES} rules`);
158	  const rules: CommandRule[] = doc.rules.map((raw, i) => {
159	    const f = `rules[${i + 1}]`;
160	    if (!isObject(raw)) throw new Error(`${f}: must be an object`);
161	    for (const key of Object.keys(raw)) if (!KNOWN_FIELDS.has(key)) throw new Error(`${f}.${key}: unknown field`);
162	    const decision = raw.decision;
163	    if (typeof decision !== "string" || !DECISIONS.includes(decision as RuleDecision)) throw new Error(`${f}.decision: must be one of ${DECISIONS.join(", ")}`);
164	    return {
165	      index: i + 1,
166	      prefix: parsePrefix(raw.prefix, `${f}.prefix`),
167	      decision: decision as RuleDecision,
168	      justification: text(raw.justification, `${f}.justification`),
169	      match: parseExamples(raw.match, `${f}.match`),
170	      notMatch: parseExamples(raw.notMatch, `${f}.notMatch`),
171	    };
172	  });
173	  const set: CommandRuleSet = { rules, ...(file ? { file } : {}) };
174	  // Examples are the rule's own test: each must agree with what the whole set actually decides.
175	  for (const rule of rules) {
176	    rule.match.forEach((example, i) => {
177	      const verdict = decideCommand(set, example);
178	      if (!verdict) throw new Error(`rules[${rule.index}].match[${i}]: "${example}" is decided by no rule (an allow rule never covers a command with shell-active characters)`);
179	      if (verdict.decision !== rule.decision || !verdict.rules.some((r) => r.index === rule.index)) {
180	        throw new Error(`rules[${rule.index}].match[${i}]: "${example}" is ${verdict.decision} by rule ${verdict.rule.index}, not ${rule.decision} by rule ${rule.index}`);
181	      }
182	    });
183	    rule.notMatch.forEach((example, i) => {
184	      const verdict = decideCommand(set, example);
185	      if (verdict?.rules.some((r) => r.index === rule.index)) throw new Error(`rules[${rule.index}].notMatch[${i}]: "${example}" is ${verdict.decision} by this rule, but is listed as not matching`);
186	    });
187	  }
188	  return set;
189	}
190	
191	/** Reads the operator's rules file. A missing file is an empty set; an unreadable or invalid one throws with the reason. */
192	export function readCommandRulesFile(file: string): CommandRuleSet {
193	  let raw: string;
194	  try {
195	    raw = fs.readFileSync(file, "utf8");
196	  } catch (error) {
197	    if ((error as NodeJS.ErrnoException).code === "ENOENT") return NO_COMMAND_RULES;
198	    throw new Error(`command_rules.json: cannot read ${file}: ${(error as Error).message}`);
199	  }
200	  let parsed: unknown;
201	  try {
202	    parsed = JSON.parse(raw);
203	  } catch {
204	    throw new Error(`command_rules.json: ${file} is not valid JSON`);
205	  }
206	  return parseCommandRules(parsed, file);
207	}
208	
209	export function describePrefix(rule: CommandRule): string {
210	  return rule.prefix.map((alternatives) => (alternatives.length === 1 ? alternatives[0] : `(${alternatives.join("|")})`)).join(" ");
211	}
