/**
 * Approval Policy Framework
 * Nexus SPEC-01 §5.1, §5.2 — Safe Execution Defaults (DEC-01, as amended)
 */
import { EffectClass } from "./capabilities.js";

export type ApprovalMode = "auto" | "review" | "read-only";

export interface PolicyContext {
  mode: ApprovalMode;
  /** Workspace trust is reported separately; it never selects or widens tool authority. */
  trusted: boolean;
  sandbox?: boolean | string;
  approvedEgressOrigins?: Set<string>;
  egressOrigin?: string;
  isUntrustedSource?: boolean;
  fullAccess?: boolean;
}

export class ApprovalPolicy {
  /**
   * Decides whether an operator decision is required before executing a capability with effect class `effect`.
   * Permission mode controls tool approvals independently of workspace trust:
   * - Review mode asks before writes, commands and egress.
   * - Auto mode allows writes and commands; egress asks once per origin per session.
   * - Untrusted context sources remain distinguishable from workspace trust.
   * - --yes / fullAccess forces auto for write and exec.
   */
  public requiresDecision(effect: EffectClass, context: PolicyContext): boolean {
    const { mode, approvedEgressOrigins, egressOrigin, isUntrustedSource, fullAccess } = context;

    // Full access (--yes / operator force auto) bypasses confirmation prompts for write and exec
    if (fullAccess) {
      if (effect === "egress") {
        if (egressOrigin && approvedEgressOrigins?.has(egressOrigin)) return false;
        // In fullAccess / --yes mode, egress does not prompt if no interactive operator is present
        return false;
      }
      return false;
    }

    // read_workspace, delegate, internal never require an operator decision
    if (effect === "read_workspace" || effect === "delegate" || effect === "internal") {
      return false;
    }

    if (mode === "read-only") {
      // In read-only mode, mutating tools are denied directly by read-only policy rather than prompting the operator
      return false;
    }

    if (mode === "review") {
      if (effect === "write_workspace" || effect === "exec") {
        return true;
      }
      if (effect === "egress") {
        if (egressOrigin && approvedEgressOrigins?.has(egressOrigin)) {
          return false;
        }
        return true;
      }
      if (effect === "context_inject") return Boolean(isUntrustedSource);
      return false;
    }

    // mode === "auto"
    if (mode === "auto") {
      if (effect === "write_workspace") {
        return false;
      }
      if (effect === "exec") {
        return false;
      }
      if (effect === "egress") {
        // Egress asks on the first call per origin per session, then allowed for that origin
        if (egressOrigin && approvedEgressOrigins?.has(egressOrigin)) {
          return false;
        }
        return true;
      }
      if (effect === "context_inject") {
        return Boolean(isUntrustedSource);
      }
      return false;
    }

    return false;
  }
}

export const defaultApprovalPolicy = new ApprovalPolicy();
/**
 * The operator's egress inspector policy. It comes from the operator's own environment (`NEXUS_EGRESS_POLICY`, a JSON object),
 * never from `.nexus-security.json`: that file belongs to the repository, and a repository must not be able to switch the
 * guard off or exempt a host. Kept apart from the inspector so the security manager can read it without importing the code
 * that imports the security manager.
 */

export type EgressMode = "block" | "record" | "off";

export interface EgressPolicy {
  mode: EgressMode;
  /** Hosts that may receive secrets: exact (`api.github.com`) or a suffix wildcard (`*.corp.example`). */
  allowDestinations: string[];
}

export const DEFAULT_EGRESS_POLICY: EgressPolicy = { mode: "block", allowDestinations: [] };

const MODES: readonly EgressMode[] = ["block", "record", "off"];

/** Strict reading of the operator's `egressInspector` block; an invalid one falls back to the safe default (block), never to off. */
export function parseEgressPolicy(raw: unknown): EgressPolicy {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return { ...DEFAULT_EGRESS_POLICY, allowDestinations: [] };
  const r = raw as Record<string, unknown>;
  const allow = Array.isArray(r.allowDestinations) ? r.allowDestinations.filter((h): h is string => typeof h === "string" && /^(?:\*\.)?[A-Za-z0-9.-]{1,253}$/.test(h)) : [];
  return { mode: MODES.includes(r.mode as EgressMode) ? (r.mode as EgressMode) : "block", allowDestinations: allow };
}

/**
 * The policy in force. `env.NEXUS_EGRESS_POLICY` is the operator's own setting (`{"mode":"record","allowDestinations":[...]}`);
 * a project `.env` cannot set it (it is not a per-project key). A value that does not parse as JSON falls back to the safe
 * default. The workspace's `.nexus-security.json` is deliberately not consulted: see `workspaceRelaxesEgress`.
 */
export function egressPolicyFromEnv(env: NodeJS.ProcessEnv = process.env): EgressPolicy {
  const raw = env.NEXUS_EGRESS_POLICY;
  if (raw === undefined || raw.trim() === "") return parseEgressPolicy(undefined);
  try {
    return parseEgressPolicy(JSON.parse(raw));
  } catch {
    return parseEgressPolicy(undefined);
  }
}

/** Whether a workspace's `egressInspector` block asks for less than the default; such a request is ignored and reported. */
export function workspaceRelaxesEgress(raw: unknown): boolean {
  const parsed = parseEgressPolicy(raw);
  return parsed.mode !== DEFAULT_EGRESS_POLICY.mode || parsed.allowDestinations.length > 0;
}
