369	/** Operator-declared workspace-relative task outputs; project files cannot populate this authority. */
370	function normalizeTrustedDeliverableFiles(workspace: string, value: unknown): string[] {
371	  if (value === undefined) return [];
372	  const entries = Array.isArray(value) ? value : [value];
373	  if (Array.isArray(value) && entries.length === 0) return [];
374	  if (entries.some((entry) => typeof entry !== "string" || !entry.trim())) {
375	    throw new Error("--deliverable-file requires one or more non-empty workspace-relative file paths.");
376	  }
377	  const root = path.resolve(workspace);
378	  const rootReal = fs.realpathSync(root);
379	  const normalized = entries.map((entry) => {
380	    const raw = (entry as string).trim();
381	    if (path.isAbsolute(raw) || raw.includes("\\") || raw.includes("\0") || /[*?{}]/.test(raw)) {
382	      throw new Error(`Invalid --deliverable-file '${raw}': use a literal workspace-relative path.`);
383	    }
384	    const candidate = path.posix.normalize(raw);
385	    const resolved = path.resolve(root, candidate);
386	    if (candidate !== raw || candidate === "." || candidate.startsWith("../") || resolved === root || !resolved.startsWith(`${root}${path.sep}`)) {
387	      throw new Error(`Invalid --deliverable-file '${raw}': path must stay inside the workspace and be normalized.`);
388	    }
389	    if (/(^|\/)(?:test|tests|__tests__)(\/|$)|(?:^|\/)test[^/]*\.[^/]+$/i.test(candidate)) {
390	      throw new Error(`Invalid --deliverable-file '${raw}': test and oracle files cannot be declared as product deliverables.`);
391	    }
392	    let cursor = root;
393	    for (const part of candidate.split("/")) {
394	      cursor = path.join(cursor, part);
395	      try {
396	        const stat = fs.lstatSync(cursor);
397	        const real = fs.realpathSync(cursor);
398	        const relative = path.relative(rootReal, real);
399	        if (stat.isSymbolicLink() || relative === ".." || relative.startsWith(`..${path.sep}`) || path.isAbsolute(relative)) {
400	          throw new Error(`Invalid --deliverable-file '${raw}': symlinked or external paths are not permitted.`);
401	        }
402	      } catch (error: any) {
403	        if (error?.code === "ENOENT") break;
404	        throw error;
405	      }
406	    }
407	    return candidate;
408	  });
409	  return [...new Set(normalized)].sort();
410	}
